node --input-type=module <<'EOF'
import {readdir,readFile} from 'node:fs/promises';import {join} from 'node:path';import {homedir,tmpdir} from 'node:os';
const configs=[];
for(const dir of [join(homedir(),'.opencut','mcp-classic-bridges'),join(tmpdir(),'opencut','mcp-classic-bridges')]){try{for(const file of await readdir(dir)){if(!file.endsWith('.json'))continue;try{const c=JSON.parse(await readFile(join(dir,file),'utf8'));process.kill(c.pid,0);if(c.version===2)configs.push(c);}catch{}}}catch{}}
const unique=[...new Map(configs.map(c=>[c.baseUrl,c])).values()].sort((a,b)=>b.createdAtMs-a.createdAtMs);
for(const c of unique.slice(0,2)){
 try{const headers={Authorization:[REDACTED] ${c.token}`,'Content-Type':'application/json'};
 const health=await fetch(c.baseUrl+'/bridge/status',{headers,signal:AbortSignal.timeout(3000)});if(!health.ok)continue;
 // Missing required session/project fields: cannot become a valid editor state.
 const probe=await fetch(c.baseUrl+'/bridge/state',{method:'PUT',headers,body:JSON.stringify({invalidDiagnosticPadding:'x'.repeat(2*1024*1024+100)}),signal:AbortSignal.timeout(5000)});
 console.log({bridgePid:c.pid,healthy:health.status,oversizedInvalidBody:probe.status});
 }catch(e){console.log({bridgePid:c.pid,error:e.name})}
}
EOF

